C7 = [
("s3","Welke elementen met vier elektronen in de buitenste schil zijn voor halfgeleiders belangrijk?","Koolstof (C), silicium (Si) en germanium (Ge). Zuiver silicium en germanium zijn isolatoren; germanium isoleert minder goed."),
("s4","Hoe zijn de atomen in een siliciumkristal verbonden?","Ze delen hun vier buitenste elektronen met hun buren en vormen zo een gezamenlijke buitenste schil van 8 elektronen. Dat is een stabiele toestand: er is geen aanleiding voor elektronen om te verplaatsen."),
("s5","Wat gebeurt er met de weerstand van een halfgeleider bij hogere temperatuur?","Die wordt kleiner (NTC). Bij metalen neemt de weerstand juist toe (PTC)."),
("s5","Hoe maak je van zuiver silicium een geleider?","Door een heel klein beetje (circa 1 op 100 miljoen atomen) van een stof met 3 of 5 elektronen in de buitenste schil toe te voegen. Dat heet doteren."),
("s5","Wat is een gat?","Een plaats in het kristalrooster waar een elektron ontbreekt, ontstaan door een element met 3 elektronen in de buitenste schil. Gaten kunnen zich net zo gemakkelijk verplaatsen als elektronen."),
("s5","Is een gedoteerd halfgeleiderkristal elektrisch geladen?","Nee, het blijft elektrisch neutraal, want de toegevoegde atomen zijn zelf ook neutraal."),
("s6","Wat is P-materiaal en wat is N-materiaal?","P-materiaal is gedoteerd met een element met 3 buitenelektronen (bijvoorbeeld borium): er zijn gaten. N-materiaal is gedoteerd met een element met 5 buitenelektronen (bijvoorbeeld fosfor): er zijn vrije elektronen."),
("s6","Wat is een PN-overgang (PN-junctie)?","De grens tussen P-materiaal en N-materiaal in één kristal."),
("s6","Wat is de uitputtingszone?","De zone langs de junctie zonder vrije ladingdragers. Elektronen en gaten hebben elkaar daar geneutraliseerd (recombinatie). De zone blokkeert de stroom."),
("s6","Wat gebeurt er met de uitputtingszone als je + op de N-kant en − op de P-kant aansluit?","De zone wordt breder: de ladingdragers trekken weg van de junctie. Er loopt geen stroom (sperrichting)."),
("s6","Wat gebeurt er als je + op de P-kant en − op de N-kant aansluit?","Elektronen en gaten worden naar de junctie getrokken, de uitputtingszone verdwijnt en er loopt stroom (doorlaatrichting)."),
("s7","Welke aansluiting van een diode is de anode en welke de kathode?","De P-aansluiting is de anode, de N-aansluiting de kathode. De doorlaatrichting (technische stroomrichting) is van anode naar kathode."),
("s7","Wat is het ezelsbruggetje voor de aansluitingen van een diode?","KNAP: Kathode Negatief, Anode Positief (in doorlaatrichting)."),
("s7","Wat is de drempelspanning van een siliciumdiode en van een germaniumdiode?","Silicium ongeveer 0,6 à 0,7 V, germanium ongeveer 0,2 V. Pas daarboven geleidt de diode in doorlaatrichting."),
("s7","Wat is de sperspanning van een normale siliciumdiode?","Enkele tientallen volt of meer (diodes voor honderden volt bestaan ook). Dat is dus groter dan 10 V."),
("s7","In welke situatie is een diode gesperd?","Als de kathode positiever is dan de anode (spanning in sperrichting)."),
("s7","Welke spanning heb je nodig om een diode in doorlaatrichting stroom te laten geleiden?","Minstens de drempelspanning. Als de anode een lagere spanning heeft dan de kathode + drempelspanning, geleidt hij niet."),
("s10","Wat is lekstroom?","Het kleine stroompje dat in sperrichting toch nog loopt."),
("s10","Waarvan hangt de lekstroom vooral af?","Sterk van de temperatuur: hij neemt sterk toe bij hogere temperatuur. Verder van de uitvoering van de diode en de aangelegde spanning."),
("s10","Wat is het verschil in lekstroom tussen silicium en germanium?","Bij silicium is de lekstroom ruwweg 100 keer zo klein als bij een vergelijkbare germaniumdiode."),
("s10","Wat is de maximale werktemperatuur van silicium- en germaniumdioden?","Silicium ongeveer 150 °C, germanium ongeveer 70 à 80 °C."),
("s10","Wat bepaalt de maximale doorlaatstroom van een halfgeleiderdiode?","De maximale temperatuur van het kristal (de warmte die het kristal aankan)."),
("s11","Formule voor de dissipatie in een diode?","P = I_F · U_D (voorwaartse stroom × spanning over de diode). Benaderd: Si P ≈ I_F · 0,6 V, Ge P ≈ I_F · 0,2 V."),
("s11","Een siliciumdiode voert 2 A in doorlaatrichting. Hoeveel dissipeert hij ongeveer?","P ≈ 2 A × 0,6 V = 1,2 W."),
("s12","Waarom gedraagt een diode in sperrichting zich als een kleine condensator?","De uitputtingszone isoleert en is het diëlektricum; de dikte ervan is de ‘plaatafstand’."),
("s12","Hoe stuur je de capaciteit van zo’n diode?","Met de sperspanning: een hogere sperspanning maakt de uitputtingszone dikker, dus de capaciteit kleiner."),
("s13","Wat is een zenerdiode?","Een diode die in sperrichting geleidt zodra de zenerspanning wordt bereikt. Als de stroom beperkt blijft, blijft de diode heel en staat de zenerspanning over hem."),
("s13","Waarvoor gebruik je een zenerdiode meestal?","Om een (vrijwel) constante spanning te maken, bijvoorbeeld een referentiespanning in een gestabiliseerde voeding."),
("s14","Hoe werkt een LED?","Bij de PN-overgang ontstaat bij recombinatie van een elektron en een gat een foton (licht). Een LED werkt in doorlaatrichting."),
("s14","Wat is de drempelspanning van een LED?","Afhankelijk van de kleur ongeveer 1,7 V (rood) tot 2,8 à 4,6 V (blauw). Altijd hoger dan 0,7 V van een siliciumdiode."),
("s14","Waarom heeft een LED meestal een serieweerstand nodig?","Om de stroom te beperken. Zonder weerstand op bijvoorbeeld 12 V brandt hij direct door."),
("s14","Welke stroom heeft een LED gewoonlijk?","Ongeveer 20 mA bij oudere typen; moderne typen lichten al duidelijk op bij 5 tot 10 mA."),
("s14","Uit welk materiaal bestaat een LED?","Meestal uit kristallen met gallium, arseen en andere elementen, niet uit silicium of germanium."),
("s15","Welke dioden-symbolen moet je herkennen?","Gelijkrichtdiode, capaciteitsdiode (varicap), zenerdiode en LED. De doorlaatrichting is de richting van de pijl, van anode naar kathode."),
("s17","Waarom heb je gelijkrichting nodig?","Het lichtnet levert wisselspanning (230 V, 50 Hz), maar bijna alle elektronica, ook zenders en ontvangers, werkt op gelijkspanning."),
("s18","Hoe werkt enkelzijdige gelijkrichting?","Eén diode laat één halve periode van de wisselspanning door en houdt de andere tegen."),
("s18","Wat gebeurt er als je de diode in een enkelzijdige gelijkrichter omdraait?","Dan worden de negatieve halve perioden doorgelaten: de uitgangsspanning is negatief."),
("s18","Wat doet een afvlakcondensator?","Hij laadt op tijdens de doorgelaten halve periode en levert stroom tussen de halve perioden, zodat de spanning vlakker wordt."),
("s18","Wanneer werkt een afvlakcondensator het best?","Hoe groter de condensator en hoe kleiner het stroomverbruik, des te vlakker de gelijkspanning."),
("s18","Wat is de onbelaste uitgangsspanning van een gelijkrichter met afvlakcondensator?","U_max = U_eff · √2 (de topwaarde van de wisselspanning)."),
("s18","Wat geeft een DC-voltmeter aan via een gelijkrichter zonder afvlakcondensator?","De gemiddelde waarde van de gelijkgerichte spanning (de oppervlakte onder de curve), want de wijzer kan 50 Hz niet volgen."),
("s19","Hoe groot moet de sperspanning van een gelijkrichtdiode minstens zijn?","Minstens 2 × U_max = 2 · √2 · U_eff, want de condensator staat op U_max terwijl de anode de negatieve piek −U_max bereikt."),
("s19","Welke sperspanning heeft een diode nodig voor 100 V eff en voor 230 V eff?","Voor 100 V eff minstens 300 V, voor 230 V eff minstens ongeveer 700 V (met veiligheidsmarge)."),
("s19","Waarvan hangt de diodekeuze in een gelijkrichter af?","Zowel van de maximale sperspanning als van de maximale stroom."),
("s19","Twee dioden in serie, met verschillende maximale sperspanningen. Waar let je op?","De hoogste toelaatbare spanning wordt begrensd door de diode met de laagste maximumspanning (zonder spanningsverdeling door weerstanden)."),
("s20","Hoe werkt tweezijdige gelijkrichting?","Beide halve perioden worden benut: de negatieve halve periode wordt omgekeerd (op de kop gezet) in plaats van tegengehouden."),
("s20","Uit hoeveel dioden bestaat een bruggelijkrichter, en welke twee geleiden tegelijk?","Vier dioden. Per halve periode geleiden twee tegenover elkaar liggende dioden (D2/D3 en D4/D1), de andere twee sperren."),
("s20","Hoe kan tweezijdige gelijkrichting met slechts twee dioden?","Met een trafo met middenaftakking (0 V). De uiteinden zijn om beurten positief; zo voert steeds één diode stroom."),
("s20","Wat levert een tweezijdige gelijkrichter op die een enkelzijdige niet levert?","Een hogere frequentie van de rimpel (100 Hz i.p.v. 50 Hz) en dus makkelijker afvlakken."),
("s20","Een trafo met middenaftakking en twee dubbelzijdige gelijkrichters. Wat levert dat op?","Een positieve én een negatieve gelijkspanning ten opzichte van de middenaftakking (0 V)."),
("s21","Waaruit bestaat een klassiek afvlakfilter?","Uit twee elektrolytische condensatoren (elco’s) en een smoorspoel met ijzerkern."),
("s21","Waarom gebruik je elco’s en een smoorspoel met ijzerkern in een voedingsfilter?","Voor 50 Hz geven elco’s een hoge capaciteit en de ijzerkern een hoge zelfinductie. Beide zijn niet geschikt voor HF."),
("s21","Wat doet de smoorspoel in een afvlakfilter?","Hij werkt veranderingen in de stroom tegen, zodat de tweede condensator een bijna constante stroom krijgt en de rimpel grotendeels verdwijnt."),
("s21","Welke waarde hebben afvlakcondensatoren in een netvoeding ongeveer?","Enkele honderden tot duizenden microfarad (µF)."),
("s22","Wat is een capaciteitsdiode (varicap)?","Een diode die in sperrichting als regelbare condensator werkt. De sperspanning bepaalt de capaciteit."),
("s22","Hoe verandert de capaciteit van een varicap als de sperspanning toeneemt?","De capaciteit wordt kleiner."),
("s22","Waarvoor gebruik je een varicap?","Om de resonantiefrequentie van een LC-kring te veranderen (verstemmen)."),
("s22","Hoe groot is de capaciteit van een varicap ongeveer?","Maximaal in de buurt van 50 pF."),
("s22","Hoe verander je de resonantiefrequentie van een kring met een factor 2?","f_res is omgekeerd evenredig met √C. Een factor 2 hoger vraagt een 4 keer kleinere capaciteit."),
("s22","Waarom staat in een varicapschakeling een hoge weerstand tussen regelspanning en kring?","Een lage weerstand zou de Q van de kring bederven."),
("s23","Hoe sluit je een zenerdiode aan en waarom met een voorschakelweerstand?","In sperrichting. De weerstand begrenst de stroom, zodat de diode niet overbelast raakt."),
("s23","Formule voor de stroom door een zenerdiode met voorschakelweerstand?","I = (U_bron − U_Z) / R (tweede wet van Kirchhoff: U_bron = U_R + U_Z)."),
("s23","Bron 10 V, zenerspanning 6,8 V, R = 1 kΩ. Hoe groot is de stroom en de dissipatie?","I = (10 − 6,8) / 1000 = 3,2 mA. P = 6,8 V × 3,2 mA ≈ 22 mW."),
("s23","Hoe bereken je de voorschakelweerstand als er ook een belasting is?","R_s = (U_bron − U_Z) / (I_Z + I_belasting). De stroom door R_s is de som van de stroom door de zener en de belasting."),
("s23","Wat verandert er aan de zenerspanning als de stroom door de zener varieert?","Heel weinig: dat is juist de bedoeling. Een kleine spanningsverandering bij een grote stroomverandering geeft een stabiele spanning."),
("s23","Wat gebeurt er met een zenerdiode als de stroom te groot wordt?","Hij raakt oververhit en gaat kapot. Houd de dissipatie P = U_Z · I_Z binnen de maximale waarde."),
("s23","Kun je een zenerdiode ook gebruiken om een spanning te verlagen?","Ja: in serie met de voedingsleiding. De spanning daalt dan met de zenerspanning."),
("s24","Welke aanduidingen hebben Europese en Amerikaanse diodetypen?","Amerikaanse typen beginnen met 1N. Europese typen beginnen vrijwel altijd met een letter (A voor germanium, B voor silicium)."),
("s24","Hoe herken je de anode van een LED?","Het langste pootje is de anode."),
("s24","Hoeveel aansluitingen heeft een brugschakeling en welke zijn de wisselspanningsaansluitingen?","Vier. De wisselstroomaansluitingen zijn gemarkeerd met een golfje (~) of AC."),
]

